PADROES_ANTIGOS = {"Essenza", "Largo do Jesuítas, 64", "Studio Industrial"}


def preencher_o_que_ele_informou(apps, schema_editor):
    """Grava os dados da empresa, sem passar por cima do que alguém tiver digitado.

    A regra é a mesma do resto do sistema: o que a loja escreveu na tela ganha sempre.
    Só é preenchido o campo que está em branco ou que ainda carrega o padrão antigo —
    assim esta migração pode rodar num servidor em que ele já tenha corrigido alguma
    coisa à mão sem apagar a correção dele.
    """
    DadosDaEmpresa = apps.get_model("compras", "DadosDaEmpresa")
    registro = DadosDaEmpresa.objects.filter(pk=1).first()
    if registro is None:
        # A linha nasce na primeira vez que alguém abre a tela; aí ela já nasce com
        # os padrões do modelo, e esta migração não tem o que fazer.
        DadosDaEmpresa.objects.create(pk=1, **INFORMADO)
        return
    mudou = []
    for campo, valor in INFORMADO.items():
        atual = (getattr(registro, campo) or "").strip()
        if not atual or atual in PADROES_ANTIGOS:
            setattr(registro, campo, valor)
            mudou.append(campo)
    if mudou:
        registro.save(update_fields=mudou)


